import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts (events with ts <= high_ts are already applied)
    high_ts = None
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]

    if high_ts is not None:
        events = events[events["event_ts"] > high_ts]

    # Deterministic, sequential application order per item: event_ts asc, then event_seq asc
    events = events.sort_values(
        ["item_id", "event_ts", "event_seq"], kind="mergesort"
    )

    # Capture original dtypes to try to preserve them on output
    qty_dtype = target["qty_on_hand"].dtype if "qty_on_hand" in target.columns else None
    ts_dtype = target["last_event_ts"].dtype if "last_event_ts" in target.columns else None

    # Build initial state from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"],
        }

    # Apply events sequentially per item
    for _, ev in events.iterrows():
        item = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        ts = ev["event_ts"]

        if op == "R":
            if item in state:
                state[item]["qty_on_hand"] = state[item]["qty_on_hand"] + qty
            else:
                state[item] = {"qty_on_hand": 0 + qty, "last_event_ts": ts}
            state[item]["last_event_ts"] = ts

        elif op == "A":
            if item in state:
                state[item]["qty_on_hand"] = qty
            else:
                state[item] = {"qty_on_hand": qty, "last_event_ts": ts}
            state[item]["last_event_ts"] = ts

        elif op == "D":
            if item in state:
                del state[item]
            # if not present, deleting a non-existent item is a no-op

    if state:
        result = pd.DataFrame(
            [
                {
                    "item_id": k,
                    "qty_on_hand": v["qty_on_hand"],
                    "last_event_ts": v["last_event_ts"],
                }
                for k, v in state.items()
            ]
        )
        result = result.sort_values("item_id", kind="mergesort").reset_index(drop=True)
    else:
        result = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    # Try to preserve original dtypes where possible
    if qty_dtype is not None and "qty_on_hand" in result.columns:
        try:
            result["qty_on_hand"] = result["qty_on_hand"].astype(qty_dtype)
        except (ValueError, TypeError):
            pass
    if ts_dtype is not None and "last_event_ts" in result.columns:
        try:
            result["last_event_ts"] = result["last_event_ts"].astype(ts_dtype)
        except (ValueError, TypeError):
            pass

    return {"new_snapshot": result}
